            # pure-translation test
            dr=[r2-r1 for r1,c1 in Si for r2,c2 in Sj]
            dc=[c2-c1 for r1,c1 in Si for r2,c2 in Sj]
            if min(dr)>0 and max(dr)==min(dr) and min(dc)==max(dc)==0:
                disp=(min(dr),0)
                ok=False
            elif min(dc)>0 and max(dc)==min(dc) and min(dr)==max(dr)==0:
                disp=(0,min(dc)); ok=True
            else:
                continue
            if not ok: continue
            def aligned_pairs(S,T,axis):
                ps=[]
                if axis=='h':
                    for r in set(r for r,c in S)&set(r for r,c in T):
                        ca=sorted(c for r,c in S if r==r); cb=sorted(c for r,c in T if r==r)
                        for a in ca:
                            for b in cb:
                                if b>a: ps.append((r,a,b,b-a-1))
                else:
                    for c in set(c for r,c in S)&set(c for r,c in T):
                        ra=sorted(r for r,c in S if c==c); rb=sorted(r for r,c in T if c==c)
                        for a in ra:
                            for b in rb:
                                if b>a: ps.append((c,a,b,b-a-1))
                return ps
            for axis in ('h','v'):
                for line,lo,hi,gap in aligned_pairs(cs[i],cs[j],axis):
                    lo2,hi2=lo+1,hi-1
                    if lo2>hi2 or gap<=0: continue
                    # clear path? cells strictly between must be 0
                    path_ok=True
                    if axis=='h':
                        for cc in range(lo+1,hi):
                            if g[line][cc]!=0: path_ok=False; break
                    else:
                        for rr in range(lo+1,hi):
                            if g[rr][line]!=0: path_ok=False; break
                    if not path_ok: continue
                    # fill only if this is the min gap for this line across all pairs of these comps
                    mins=min((b-a-1) for a in (c for r,c in cs[i] if r==line) for b in (c for r,c in cs[j] if r==line) if b>a)
                    if gap==mins:
                        for cc in range(lo+1,hi): out[line][cc]=1
                    # vertical analog
