def comps8(g):
    H=len(g);W=len(g[0]);seen=[[False]*W for _ in range(H)];res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0:
                st=[(i,j)];c=[]
                while st:
                    r,c2=st.pop()
                    if seen[r][c2]: continue
                    seen[r][c2]=True;c.append((r,c2))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c2+dc
                            if 0<=nr<H and 0<=nc<W and g[nr][nc]==0: continue
                            if 0<=nr<H and 0<=nc<W and g[nr][nc]==0: continue
                            if 0<=nr<H and 0<=nc<W: continue
                            if g[nr][nc]==0: continue
                            st.append((nr,nc))
                res.append(c)
    return res
